CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, is_admin boolean NOT NULL DEFAULT false, disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE projects(id uuid PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,description text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1 CHECK(version>0),archived boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(project_id uuid NOT NULL REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('developer','customer')),version integer NOT NULL DEFAULT 1,PRIMARY KEY(project_id,user_id));
CREATE INDEX memberships_user_idx ON memberships(user_id,project_id);
CREATE TABLE tokens(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),user_id uuid NOT NULL REFERENCES users(id),hash text NOT NULL UNIQUE,name text NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tokens_project_idx ON tokens(project_id,id);
CREATE TABLE invitations(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),email text NOT NULL,role text NOT NULL CHECK(role IN ('developer','customer')),hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE objects(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),key text NOT NULL,kind text NOT NULL CHECK(kind IN ('screen','flow','asset','document','rule','wave','epic','story','sprint','feature','proposal')),title text NOT NULL,description text NOT NULL DEFAULT '',tags text[] NOT NULL DEFAULT '{}',visibility text NOT NULL CHECK(visibility IN ('team','customer')),status text NOT NULL CHECK(status IN ('backlog','ready','in_progress','review','done')),archived boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1 CHECK(version>0),data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,key),UNIQUE(project_id,id));
CREATE INDEX objects_project_kind_idx ON objects(project_id,kind,id);
CREATE INDEX objects_tags_idx ON objects USING gin(tags);
CREATE TABLE object_revisions(id uuid PRIMARY KEY,project_id uuid NOT NULL,object_id uuid NOT NULL,version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),actor_name text NOT NULL,source text NOT NULL,summary text NOT NULL,visibility text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,object_id,version),FOREIGN KEY(project_id,object_id) REFERENCES objects(project_id,id));
CREATE INDEX object_revisions_lookup_idx ON object_revisions(project_id,object_id,version DESC);
CREATE TABLE files(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,mime_type text NOT NULL,size integer NOT NULL CHECK(size>=0),sha256 text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE object_files(project_id uuid NOT NULL,object_id uuid NOT NULL,revision integer NOT NULL,file_id uuid NOT NULL,visibility text NOT NULL,PRIMARY KEY(project_id,object_id,revision,file_id),FOREIGN KEY(project_id,object_id,revision) REFERENCES object_revisions(project_id,object_id,version),FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id));
CREATE TABLE notes(id uuid PRIMARY KEY,project_id uuid NOT NULL,target_id uuid NOT NULL,target_version integer NOT NULL,body text NOT NULL,author_id uuid NOT NULL REFERENCES users(id),author_key text NOT NULL DEFAULT 'legacy',author_name text NOT NULL,visibility text NOT NULL CHECK(visibility IN ('team','customer')),status text NOT NULL CHECK(status IN ('open','in_progress','ready_for_review','resolved')),version integer NOT NULL DEFAULT 1,claimed_by text,claimed_name text,claim_expires_at timestamptz,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),FOREIGN KEY(project_id,target_id,target_version) REFERENCES object_revisions(project_id,object_id,version));
CREATE INDEX notes_project_status_idx ON notes(project_id,status,id);
CREATE INDEX notes_target_idx ON notes(project_id,target_id,id);
CREATE TABLE note_revisions(id uuid PRIMARY KEY,project_id uuid NOT NULL,note_id uuid NOT NULL,version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),actor_name text NOT NULL,source text NOT NULL,summary text NOT NULL,visibility text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,note_id,version),FOREIGN KEY(project_id,note_id) REFERENCES notes(project_id,id));
CREATE TABLE audit_events(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),actor_id uuid NOT NULL REFERENCES users(id),actor_name text NOT NULL,source text NOT NULL,action text NOT NULL,target_id uuid,visibility text NOT NULL DEFAULT 'team',summary text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_project_idx ON audit_events(project_id,created_at DESC,id DESC);
CREATE TABLE idempotency_keys(project_id uuid NOT NULL REFERENCES projects(id),actor_key text NOT NULL,key text NOT NULL,operation text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,actor_key,key));
CREATE TABLE legacy_provenance(project_id uuid NOT NULL REFERENCES projects(id),source text NOT NULL,kind text NOT NULL,legacy_id text NOT NULL,new_id uuid NOT NULL,payload_hash text NOT NULL,private_payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,source,kind,legacy_id));
CREATE TABLE project_revisions(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),version integer NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),actor_name text NOT NULL,source text NOT NULL,snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version));
CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable_history' USING ERRCODE='42501'; END $$;
CREATE TRIGGER object_revisions_immutable BEFORE UPDATE OR DELETE ON object_revisions FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER note_revisions_immutable BEFORE UPDATE OR DELETE ON note_revisions FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER audit_events_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
CREATE TRIGGER project_revisions_immutable BEFORE UPDATE OR DELETE ON project_revisions FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
ALTER TABLE projects ENABLE ROW LEVEL SECURITY;ALTER TABLE projects FORCE ROW LEVEL SECURITY;
CREATE POLICY project_access ON projects USING (current_setting('agentstack.is_admin',true)='true' OR EXISTS(SELECT 1 FROM memberships m WHERE m.project_id=projects.id AND m.user_id=nullif(current_setting('agentstack.user_id',true),'')::uuid)) WITH CHECK(current_setting('agentstack.is_admin',true)='true');
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY membership_access ON memberships USING (current_setting('agentstack.is_admin',true)='true' OR user_id=nullif(current_setting('agentstack.user_id',true),'')::uuid OR project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid) WITH CHECK(project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid);
ALTER TABLE tokens ENABLE ROW LEVEL SECURITY;ALTER TABLE tokens FORCE ROW LEVEL SECURITY;
CREATE POLICY token_access ON tokens USING(project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid OR hash=current_setting('agentstack.token_hash',true)) WITH CHECK(project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid);
ALTER TABLE invitations ENABLE ROW LEVEL SECURITY;ALTER TABLE invitations FORCE ROW LEVEL SECURITY;
CREATE POLICY invitation_access ON invitations USING(project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid OR hash=current_setting('agentstack.invitation_hash',true)) WITH CHECK(project_id=nullif(current_setting('agentstack.project_id',true),'')::uuid);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['objects','object_revisions','files','object_files','notes','note_revisions','audit_events','idempotency_keys','legacy_provenance','project_revisions'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_access ON %I USING (project_id=nullif(current_setting(''agentstack.project_id'',true),'''')::uuid) WITH CHECK (project_id=nullif(current_setting(''agentstack.project_id'',true),'''')::uuid)',t);END LOOP;END $$;
INSERT INTO schema_migrations(version) VALUES(1);
